public static class ChunkCheck
{
    public static List<List<int>> Check(int[] items, int size, int endlessChunks)
    {
        if (endlessChunks == 0) return Solution.Chunks(items, size).ToList();
        return Solution.Chunks(Naturals(), size).Take(endlessChunks).ToList();
    }

    private static IEnumerable<int> Naturals()
    {
        for (var n = 1; ; n++) yield return n;
    }
}

